17	/**
18	 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
19	 *
20	 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
21	 *   GAME_CONFIG: gameConfigApply,
22	 *
23	 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
24	 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
25	 *
26	 * TWO PATHS:
27	 *  - DEFAULT (simulation): records an "applied" marker on `Server.gameConfig` and
28	 *    notifies the user. No SSH, no VM mutation. This runs under SANDBOX and, in
29	 *    production, for any family not yet verified (see below).
30	 *
31	 *  - REAL: actually pushes the settings to the live game server over SSH. Runs
32	 *    per-family (see `REAL_APPLY_FAMILIES`) rather than one blanket switch — a
33	 *    family's real path is deliberately non-destructive (read-modify-write for
34	 *    key=value files, or — for images like Palworld's that regenerate their
35	 *    config from env vars on every boot — a full container recreation with
36	 *    rollback on failure; never clobbers a config it can't find/parse) and
37	 *    fully wrapped in try/catch so a failure notifies the user but never
38	 *    crashes the worker. `ENABLE_REAL_GAMECFG=1` additionally force-enables
39	 *    every family at once, for whenever the rest have been confirmed too.
40	 *
41	 * Enable a family's real path only once its config paths / service names / apply
42	 * function have been confirmed for the actual game-server image — see
43	 * `REAL_APPLY_FAMILIES`'s own comment for what "confirmed" means in practice.
44	 */
45	
46	/** Force-enables every family's real path at once — set only once ALL of them
47	 *  have been individually confirmed, not as a way to unblock just one. */
48	const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";
49	
50	/**
51	 * Families whose real-apply path has been individually built AND verified
52	 * against the actual production image/container, so it's safe to run even
53	 * while `ENABLE_REAL_GAMECFG` stays off for everyone else.
54	 *
55	 * "verified" here means: confirmed live, end-to-end, against a real running
56	 * container — not just "the code looks right". `palworld` was added
57	 * 2026-09-05 after the previous version of `applyPalworld` was found to
58	 * silently regenerate-then-lose its own writes (see that function's comment);
59	 * the replacement was verified by actually recreating a live container with
60	 * an updated setting and reading the resulting config back off disk.
61	 *
62	 * `minecraft` added 2026-09-06: verified against a real throwaway server on
63	 * node-2 (provisioned, applied `difficulty` + `online-mode` via
64	 * `applyRealConfig` directly, read `/opt/mc/server.properties` back off disk
65	 * and confirmed both values, then destroyed the VM). The path-detection
66	 * TODO on `applyMinecraft` is resolved for the current image: the host-side
67	 * bind mount (`/opt/mc` -> `/data`) puts server.properties somewhere
68	 * `remoteLocate`'s `find` over /opt already reaches. One real, non-blocking
69	 * gap found: `mcrcon` is not installed on the image, so today every setting
70	 * falls back to "restart to apply" — correctly reported as such, never
71	 * silently claimed live — rather than the live-RCON push `tryMinecraftRcon`
72	 * would otherwise attempt for difficulty/whitelist/etc.
73	 *
74	 * `rust` added 2026-09-06 by the whole-catalog integrity sweep, after
75	 * `applyRust` was found to be writing a `server.cfg` that (a) does not exist on
76	 * this image and (b) would have been ignored even if it did — see that
77	 * function's own comment for the two live proofs. The replacement recreates the
78	 * container from `RUST_SERVER_*` env vars, and was verified by reading **every
79	 * field in the Rust schema back off the live running game** via its own RCON,
80	 * not off a config file: `server.hostname: "NXEON SWEEP RUST"`,
81	 * `server.maxplayers: "42"`, `server.worldsize: "4000"`, `server.pve: "True"`,
82	 * and `server.seed: "12345"` still at its old value — proving untouched
83	 * settings survive the recreate. Independently corroborated by the server's own
84	 * boot log, whose occlusion grid went 1750 -> 2000 (worldsize/2) across the
85	 * change. One real caveat, reported to the customer in the apply's own notes
86	 * rather than hidden: Rust reloads its entire map on restart, so an apply takes
87	 * that server offline for several minutes — far longer than Palworld's seconds.
88	 *
89	 * `valheim` added 2026-09-06 by the same sweep. Its old implementation was the
90	 * worst-behaved of the three pre-written ones — it wrote a launch-args file
91	 * nothing read and returned `ok: true`, so the customer was told "Game settings
92	 * applied" while the server was untouched. The replacement recreates the
93	 * container from `WORLD_NAME` + `SERVER_ARGS`, and was verified against the
94	 * REAL RUNNING PROCESS's argv (`-world NxeonSweepWorld … -preset hard`, from
95	 * `-world Nxeon` and no preset) plus the server genuinely creating the new
96	 * world on disk (`NxeonSweepWorld.fwl`) while keeping the old one — exactly what
97	 * the apply's own note promises the customer.
98	 */
99	/* The list itself moved to lib/game-config.ts so the SETTINGS PAGE can read
100	   the same set and warn before a customer types, rather than after the job
101	   fails. Imported, never re-declared.
102	
103	   `bedrock` added to that list 2026-09-13: had no real-apply implementation
104	   at all before this (the family wasn't even referenced in this file) —
105	   every Bedrock customer's checkout-time settings silently never applied,
106	   always falling through to the simulation-path error further down. Built
107	   `applyBedrock` (below) against itzg/docker-minecraft-bedrock-server's
108	   actual documented env vars (not a 1:1 rename of the schema's field keys —
109	   `max-players` -> `MAX_PLAYERS`, `white-list` -> `ALLOW_LIST`, etc.) and
110	   verified live against a real customer's running container: applied all 6
111	   settings, then read every one of GAMEMODE/DIFFICULTY/MAX_PLAYERS/
112	   ALLOW_CHEATS/LEVEL_NAME/VERSION back off `docker inspect` and confirmed
113	   each matched, with the container reporting "(healthy)" and the existing
114	   world genuinely reopened (no "CREATING VANILLA WORLD" banner, world data
115	   on disk unchanged) rather than recreated fresh. */
116	
117	function familyRealApplyEnabled(family: string): boolean {
118	  return REAL_APPLY_ENABLED || REAL_APPLY_FAMILIES.has(family);
119	}
120	
121	const CONNECT_TIMEOUT_MS = 15_000;
122	const EXEC_TIMEOUT_MS = 30_000;
123	
124	async function notify(userId: string, title: string, body?: string, href?: string) {
125	  try {
126	    await db.notification.create({ data: { userId, title, body, href } });
127	  } catch (e) {
128	    console.error("[game-config] notify failed", e);
129	  }
130	}
