456	// ---------------------------------------------------------------------------
457	// key=value file helpers (server.properties)
458	// ---------------------------------------------------------------------------
459	
460	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
461	function updateKeyValue(content: string, updates: Record<string, string>): string {
462	  const lines = content.split(/\r?\n/);
463	  const seen = new Set<string>();
464	  for (let i = 0; i < lines.length; i++) {
465	    const trimmed = lines[i].trim();
466	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
467	    const eq = lines[i].indexOf("=");
468	    if (eq < 0) continue;
469	    const key = lines[i].slice(0, eq).trim();
470	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
471	      lines[i] = `${key}=${updates[key]}`;
472	      seen.add(key);
473	    }
474	  }
475	  for (const k of Object.keys(updates)) {
476	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
477	  }
478	  return lines.join("\n");
479	}
480	
481	/** Read a `key=value` file into a map (comments/blank lines ignored). */
482	function parseKeyValue(content: string): Record<string, string> {
483	  const out: Record<string, string> = {};
484	  for (const line of content.split(/\r?\n/)) {
485	    const t = line.trim();
486	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
487	    const eq = line.indexOf("=");
488	    if (eq < 0) continue;
489	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
490	  }
491	  return out;
492	}
493	
494	// ---------------------------------------------------------------------------
495	// space-separated convar/cvar helpers (rust server.cfg, cs2 server.cfg)
496	// ---------------------------------------------------------------------------
497	
498	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
499	function updateConvars(content: string, updates: Record<string, string>): string {
500	  const lines = content.split(/\r?\n/);
501	  const seen = new Set<string>();
502	  for (let i = 0; i < lines.length; i++) {
503	    const t = lines[i].trim();
504	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
505	    const sp = t.search(/\s/);
506	    const key = sp < 0 ? t : t.slice(0, sp);
507	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
508	      lines[i] = `${key} ${updates[key]}`;
509	      seen.add(key);
510	    }
511	  }
512	  for (const k of Object.keys(updates)) {
513	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
514	  }
515	  return lines.join("\n");
516	}
517	
518	const bool = (v: unknown) => (v === true || v === "true" || v === "on" ? "true" : "false");
519	
520	// ---------------------------------------------------------------------------
521	// Container recreation — shared by every family whose image takes its settings
522	// from ENVIRONMENT VARIABLES rather than an editable config file
523	// ---------------------------------------------------------------------------
524	
525	/**
526	 * Read a container's current environment as a map.
527	 *
528	 * Recreating a container means re-supplying its WHOLE environment, not just the
529	 * keys being changed: the images this is used for get most of their defaults
530	 * from their own Dockerfile `ENV`s, and dropping those would silently reset
531	 * settings the customer never touched. `PATH` is excluded — the image always
532	 * injects a correct one, and carrying ours over would be wrong.
533	 */
534	async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
535	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
536	  if (inspect.code !== 0) return null;
537	  let envArr: string[];
538	  try {
539	    envArr = JSON.parse(inspect.stdout.trim());
540	  } catch {
541	    return null;
542	  }
543	  const envMap = new Map<string, string>();
544	  for (const entry of envArr) {
545	    const idx = entry.indexOf("=");
546	    if (idx < 0) continue;
547	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
548	  }
549	  envMap.delete("PATH");
550	  return envMap;
551	}
552	
553	/** The exact image reference (repo:tag) a running container was created from. */
554	async function readContainerImage(conn: Client, container: string): Promise<string | null> {
555	  const res = await execRemote(conn, `docker inspect ${container} --format '{{.Config.Image}}'`);
556	  if (res.code !== 0) return null;
557	  const image = res.stdout.trim();
558	  return image || null;
559	}
