659	
660	const MINECRAFT_CONTAINER = "mc";
661	/**
662	 * Must track prisma/catalog.ts's minecraft template image tag exactly — see
663	 * that file's own comment on why `:java21` (not bare `:latest`) is required
664	 * for the platform's pinned default VERSION to actually run on a matching
665	 * Java runtime. A version-only settings change recreates the container from
666	 * THIS constant, so drifting the two out of sync would silently reintroduce
667	 * the wrong-Java-version bug for anyone who edits their version in Settings.
668	 */
669	const MINECRAFT_IMAGE = "itzg/minecraft-server:java21";
670	/** Ports + volume exactly as prisma/catalog.ts's minecraft template provisions them. */
671	const MINECRAFT_RUN_FLAGS = "-p 25565:25565 -p 25575:25575 -v /opt/mc:/data --env-file /root/mc.env";
672	
673	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
674	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
675	  // image. These candidates cover the common layouts; if none match we soft-fail
676	  // rather than create a stray server.properties in the wrong place.
677	  const path = await remoteLocate(
678	    conn,
679	    [
680	      "/opt/minecraft/server.properties",
681	      "/srv/minecraft/server.properties",
682	      "/home/minecraft/server.properties",
683	      "/minecraft/server.properties",
684	      "/root/minecraft/server.properties",
685	    ],
686	    ["/opt", "/srv", "/home"],
687	    "server.properties"
688	  );
689	  if (!path) {
690	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
691	  }
692	
693	  const existing = await sftpRead(sftp, path);
694	  if (existing == null) {
695	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
696	  }
697	
698	  // server.properties keys map 1:1 to the schema field keys. VERSION is a
699	  // docker env var, not a server.properties key — it's handled separately
700	  // below via container recreate, not written to this file.
701	  const updates: Record<string, string> = {};
702	  for (const [key, val] of Object.entries(v)) {
703	    if (key === "VERSION") continue;
704	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
705	  }
706	  const next = updateKeyValue(existing, updates);
707	  await sftpWrite(sftp, path, next);
708	
709	  const applied: string[] = [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`];
710	  const notes: string[] = [];
711	
712	  // VERSION: itzg's image defaults to tracking Mojang's newest release on every
713	  // container restart unless VERSION is pinned (see prisma/catalog.ts's own
714	  // comment on this field for the live incident that found it). Also checks
715	  // the running image tag against MINECRAFT_IMAGE: a server provisioned before
716	  // the :java21 image tag existed is still on the bare (wrong-Java) image even
717	  // once VERSION itself is correctly pinned — found live 2026-09-06 on the
718	  // very Cobblemon server this field was built for, where VERSION pinned
719	  // clean but the container kept running the stale image's bundled JDK 25.
720	  // Only recreates when either actually differs from what's running, so an
721	  // ordinary gamemode/difficulty change never pays for a full container
722	  // recreate — same reasoning as `applyGameVariant`'s own no-op guard.
723	  const desiredVersion = v["VERSION"] != null ? String(v["VERSION"]) : null;
724	  if (desiredVersion) {
725	    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
726	    const currentVersion = envMap?.get("VERSION") ?? null;
727	    const currentImage = await readContainerImage(conn, MINECRAFT_CONTAINER);
728	    const imageStale = currentImage !== null && currentImage !== MINECRAFT_IMAGE;
729	    if (envMap && (currentVersion !== desiredVersion || imageStale)) {
730	      envMap.set("VERSION", desiredVersion);
731	      envMap.delete("JAVA_VERSION"); // stale, baked in by whatever image created this container — let the new image set its own
732	      await writeEnvFile(conn, sftp, "/root/mc.env", envMap);
733	      const res = await recreateGameContainer(conn, {
734	        family: "minecraft",
735	        container: MINECRAFT_CONTAINER,
736	        runFlags: MINECRAFT_RUN_FLAGS,
737	        image: MINECRAFT_IMAGE,
738	      });
739	      if (!res.ok) {
740	        notes.push(`Wrote settings, but pinning the Minecraft version failed: ${res.note}`);
741	      } else {
742	        const parts: string[] = [];
743	        if (currentVersion !== desiredVersion) {
744	          parts.push(
745	            currentVersion
746	              ? `pinned Minecraft version to ${desiredVersion} (was ${currentVersion})`
747	              : `pinned Minecraft version to ${desiredVersion} (previously untracked — following Mojang's newest release on every restart)`
748	          );
749	        }
750	        if (imageStale) parts.push(`updated the server image to run the correct Java runtime for this version (was ${currentImage})`);
751	        const summary = parts.join(" and ");
752	        applied.push(`${summary.charAt(0).toUpperCase()}${summary.slice(1)}, and restarted the server.`);
753	      }
754	    }
755	  }
756	
757	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
758	  // restart. Wrapped so RCON problems never fail the apply.
759	  try {
760	    await tryMinecraftRcon(conn, next, v, notes);
761	  } catch (e) {
762	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
763	    console.error("[game-config] minecraft rcon error", e);
764	  }
765	
766	  return {
767	    ok: true,
768	    applied,
769	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
770	  };
771	}
