773	/**
774	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
775	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
776	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
777	 */
778	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
779	  const kv = parseKeyValue(props);
780	  const enabled = kv["enable-rcon"] === "true";
781	  const password = kv["rcon.password"] ?? "";
782	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
783	  // customer's own VM — an attacker-controlled string in every sense, and one
784	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
785	  // anything that is not one is discarded rather than escaped. `shq` and the
786	  // quoting below are the second and third lines of defence; this is the first,
787	  // and it is the only one that does not depend on getting quoting right.
788	  const port = rconPort(kv["rcon.port"]);
789	  if (!enabled || !password) {
790	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
791	    return;
792	  }
793	  const which = await execRemote(conn, "command -v mcrcon || true");
794	  if (!which.stdout.trim()) {
795	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
796	    return;
797	  }
798	
799	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
800	  // runtime command set is verified for the target Minecraft build.
801	  const cmds: string[] = [];
802	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
803	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
804	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
805	  if (cmds.length === 0) return;
806	
807	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
808	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
809	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
810	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
811	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
812	  // customer's own server.properties ran as root on the hypervisor's SSH client
813	  // target with no further steps required.
814	  //
815	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
816	  // `res.code === 0` test below was a constant and this function reported
817	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
818	  // password, or was never reached. `execRemote` resolves with the real exit
819	  // code rather than rejecting, so nothing here can throw on a non-zero status —
820	  // the note just becomes true.
821	  const res = await execRemote(
822	    conn,
823	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
824	  );
825	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
826	}
