828	/**
829	 * The RCON port to talk to, from an untrusted `rcon.port` value.
830	 *
831	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
832	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
833	 * Returns a string because it is interpolated into a command line, and returning
834	 * the parsed digits — never the caller's original text — is what makes the value
835	 * safe by construction rather than by escaping.
836	 */
837	function rconPort(raw: string | undefined): string {
838	  const n = Number(String(raw ?? "").trim());
839	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
840	  return String(n);
841	}
