847	const RUST_CONTAINER = "rust";
848	const RUST_IMAGE = "didstopia/rust-server";
849	/** Ports + volume exactly as prisma/catalog.ts's Rust template provisions them. */
850	const RUST_RUN_FLAGS = "-p 28015:28015/udp -p 28016:28016 -v /opt/rust:/steamcmd/rust --env-file /root/rust.env";
851	
852	/**
853	 * Schema field key → the `didstopia/rust-server` env var that sets it.
854	 *
855	 * Read directly out of the image's own `/app/start.sh` on a real running
856	 * container (2026-09-06), not guessed — it builds the launch line with
857	 * `add_argument_pair ARGUMENTS "+server.hostname" "RUST_SERVER_NAME"` and
858	 * friends. `pve` has no env var of its own and goes through
859	 * `RUST_SERVER_STARTUP_ARGUMENTS` instead (see below).
860	 */
861	const RUST_ENV_MAP: Record<string, string> = {
862	  hostname: "RUST_SERVER_NAME",
863	  maxplayers: "RUST_SERVER_MAXPLAYERS",
864	  worldsize: "RUST_SERVER_WORLDSIZE",
865	  seed: "RUST_SERVER_SEED",
866	};
867	
868	/** Replace `<flag> <value>` in an argument string, or append the pair if absent. */
869	function upsertArg(args: string, flag: string, value: string): string {
870	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
871	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
872	  return re.test(args) ? args.replace(re, `$1${flag} ${value}`) : `${args} ${flag} ${value}`.trim();
873	}
874	
875	/** Strip `<flag> <value>` from an argument string entirely, if present. */
876	function removeArg(args: string, flag: string): string {
877	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
878	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
879	  return args.replace(re, "").trim();
880	}
881	
882	/** Replace `+convar <value>` in a Rust startup-argument string, or append it. */
883	function upsertConvarArg(args: string, convar: string, value: string): string {
884	  return upsertArg(args, `+${convar}`, value);
885	}
