887	/**
888	 * Rust → container recreation with an --env-file (NOT server.cfg editing).
889	 *
890	 * Found live 2026-09-06 during the whole-catalog sweep, and it is the SAME class
891	 * of bug as Palworld's below. The previous version of this function looked for
892	 * `<identity>/cfg/server.cfg` and wrote convars into it. Two things were wrong,
893	 * both confirmed against a real running server rather than reasoned about:
894	 *
895	 *  1. **No server.cfg exists.** Rust does not ship one; the image creates
896	 *     `bans.cfg`, `users.cfg`, `serverauto.cfg` and `relay_cfg.json` in
897	 *     `/opt/rust/server/docker/cfg/` and nothing else. `remoteLocate` only ever
898	 *     matches an EXISTING file, so every apply soft-failed with "Could not
899	 *     locate Rust server.cfg". Honest, but nothing a customer could ever change.
900	 *  2. **Even creating one would not have worked.** `didstopia/rust-server` builds
901	 *     its entire launch line from `RUST_SERVER_*` environment variables
902	 *     (`/app/start.sh`), and those convars win. Proven directly: wrote
903	 *     `server.hostname "NXEON SWEEP TEST HOSTNAME"` + `server.maxplayers 42`
904	 *     into the real cfg dir, restarted, and RCON still reported
905	 *     `Hostname: Rust Server [DOCKER]`, `MaxPlayers: 500` — the env-var values.
906	 *     Fixing only the path would have shipped a function that writes a
907	 *     correct-looking file and changes nothing, which is the precise
908	 *     "reports success, nothing happened" failure this allowlist exists to stop.
909	 *
910	 * So, exactly like Palworld: the only durable way to change these settings is to
911	 * recreate the container with updated environment variables.
912	 */
913	async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
914	  const envMap = await readContainerEnv(conn, RUST_CONTAINER);
915	  if (!envMap) {
916	    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
917	  }
918	
919	  const applied: string[] = [];
920	  const notes: string[] = [];
921	  for (const [key, val] of Object.entries(v)) {
922	    if (val == null) continue;
923	    const env = RUST_ENV_MAP[key];
924	    if (env) {
925	      envMap.set(env, String(val));
926	      applied.push(key);
927	    } else if (key === "pve") {
928	      // No RUST_SERVER_PVE exists. start.sh passes RUST_SERVER_STARTUP_ARGUMENTS
929	      // through verbatim ahead of the generated pairs, so it is the image's own
930	      // escape hatch for any convar it has no variable for.
931	      const args = envMap.get("RUST_SERVER_STARTUP_ARGUMENTS") ?? "-batchmode -load -nographics +server.secure 1";
932	      envMap.set("RUST_SERVER_STARTUP_ARGUMENTS", upsertConvarArg(args, "server.pve", bool(val)));
933	      applied.push(key);
934	    }
935	  }
936	  if (applied.length === 0) {
937	    return { ok: true, applied: [], notes: ["No changes to apply."] };
938	  }
939	
940	  await writeEnvFile(conn, sftp, "/root/rust.env", envMap);
941	
942	  const res = await recreateGameContainer(conn, {
943	    family: "rust",
944	    container: RUST_CONTAINER,
945	    runFlags: RUST_RUN_FLAGS,
946	    image: RUST_IMAGE,
947	  });
948	  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };
949	
950	  if (v["worldsize"] != null || v["seed"] != null) {
951	    notes.push("World size / seed only take effect on a fresh map — the existing save is kept until the next wipe.");
952	  }
953	  notes.push(
954	    "Rust reloads its whole map on restart, so your server will be offline for several minutes before players can rejoin."
955	  );
956	
957	  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
958	}
