112	
113	  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
114	  const action = String(p.action ?? "");
115	  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
116	  const href = `/dashboard/servers/${server.id}?tab=manage`;
117	
118	  if (SANDBOX) {
119	    await notify(
120	      server.userId,
121	      `Game service ${action} (sandbox) on ${server.hostname}`,
122	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
123	      href
124	    );
125	    return;
126	  }
127	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
128	
129	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
130	  if (action === "restart" && p.announce && spec.rcon === "source") {
131	    try {
132	      await withServerSsh(server as SftpServer, (conn) =>
133	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
