// ---------------------------------------------------------------------------
// In-guest positive confirmation — the only way to tell "the game process
// really bound its port" from "the container/service object exists".
// ---------------------------------------------------------------------------

/**
 * Ask the guest whether anything is really bound to the game's port — the
 * positive evidence `checkGamePortOpen`'s UDP path cannot get from outside
 * (see `procNetHasPort` for why silence is not proof).
 *
 * Reads the network namespace of every RUNNING container, falling back to the
 * guest's own only when no container is running. The fallback order matters
 * and is not a detail: `docker-proxy` binds every published port in the
 * guest's ROOT namespace for as long as the container is up, whether or not
 * the game inside ever listens — verified live on The Forest, whose guest
 * showed `0.0.0.0:27015` bound while the game had never started. Counting the
 * root namespace whenever a container runs would reproduce the very false
 * positive this function exists to remove. A `--network host` container is
 * unaffected: its namespace IS the root one.
 *
 * Exported from this side-effect-free module (rather than kept private in
 * worker/index.ts, where it originally lived) so `worker/game-control.ts` can
 * reuse the exact same in-guest check for GAME_POWER's start/restart —
 * importing worker/index.ts itself is unsafe anywhere else, since it runs a
 * top-level job-polling `main()` loop on import.
 *
 * ADDED TO GAME_POWER 2026-09-20: every existing health signal for
 * GAME_UPDATE and GAME_POWER start/restart only ever checked that the
 * container/systemd-service OBJECT existed and `systemctl` reported it
 * active — never that the actual game process bound its port. That is
 * precisely how a Minecraft server hardcoded onto the wrong Java image
 * (crash-looping every ~15s, `docker logs` full of a clear Java-version
 * error) went undetected: the systemd unit around a `Restart=always`
 * container reports "active" between crashes just as readily as it would for
 * a genuinely healthy server. See lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS
 * for the incident this shares its root cause with.
 *
 * Opens its own SSH connection (does not reuse a caller's already-open one) —
 * pure reads, nothing on the guest is touched.
 *
 * Returns `null` — never `false` — for anything it could not determine (SSH
 * failed, no marker in the output), so an unreachable guest can never turn a
 * healthy server into a falsely-failed check.
 */
export async function gamePortBoundInGuest(
  probeServer: { id: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
  port: number,
  protocol: "tcp" | "udp"
): Promise<boolean | null> {
  const base = protocol === "tcp" ? "tcp" : "udp";
  try {
    return await withServerSsh(probeServer as any, async (conn) => {
      const r = await exec(
        conn,
        // `docker ps` failing and `docker ps` finding nothing look identical in
        // its output, so its exit status is captured explicitly: a daemon that
        // could not be asked must read as UNKNOWN, never as "no containers, so
        // look in the root namespace" — where docker-proxy would answer for a
        // dead game.
        `if ids=$(docker ps -q 2>/dev/null); then dok=1; else dok=0; fi; ` +
          `files=""; ` +
          `for pid in $(docker inspect -f '{{.State.Pid}}' ${"$"}ids 2>/dev/null); do ` +
          `case "${"$"}pid" in ''|0) continue;; esac; ` +
          `files="${"$"}files /proc/${"$"}pid/net/${base} /proc/${"$"}pid/net/${base}6"; done; ` +
          `if [ -z "${"$"}files" ]; then ` +
          `if [ "${"$"}dok" = 1 ] && [ -z "${"$"}ids" ]; then files="/proc/net/${base} /proc/net/${base}6"; ` +
          `else echo NXNET_UNKNOWN; exit 0; fi; fi; ` +
          `echo NXNET_BEGIN; cat ${"$"}files 2>/dev/null; echo NXNET_END`,
        QUICK_TIMEOUT_MS
      );
      const begin = r.stdout.indexOf("NXNET_BEGIN");
      const end = r.stdout.indexOf("NXNET_END");
      if (begin < 0 || end < begin) {
        console.warn(
          `[worker] ${probeServer.id}: could not read ${port}/${protocol} bindings from the guest ` +
            `(${r.stdout.includes("NXNET_UNKNOWN") ? "docker could not be queried" : "no marker in the reply"})`
        );
        return null;
      }
      const table = r.stdout.slice(begin + "NXNET_BEGIN".length, end);
      const bound = procNetHasPort(table, port, { tcpListeningOnly: protocol === "tcp" });
      if (!bound) {
        console.warn(`[worker] ${probeServer.id}: nothing in the guest is bound to ${port}/${protocol}`);
      }
      return bound;
    });
  } catch (e) {
    console.warn(
      `[worker] ${probeServer.id}: could not ask the guest about ${port}/${protocol} bindings: ${String((e as Error)?.message ?? e)}`
    );
    return null;
  }
}

