const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
const text = out.stdout;
if (/NXGP:UNIT:NONE/.test(text)) {
  await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
  throw new Error("game power: no service unit found");
}
const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
if (!/NXGP:END/.test(text) || rc !== 0) {
  await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
  throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
}

// FOUND LIVE 2026-09-20: this used to notify success on rc===0 + an END
// marker alone, without ever checking `state` — so a unit that restarted
// straight into "failed" (or stayed "activating"/crash-looping) was still
// reported to the customer as "restarted (now failed)", i.e. success. A
// `Restart=always` unit around a crash-looping container (exactly what a
// wrong-Java-version Minecraft image produces — see
// lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS) reports "active" between
// crashes just as readily as a genuinely healthy server, so `systemctl`
// alone was never going to be enough either way.
if (action !== "stop" && state !== "active") {
  await notify(
    server.userId,
    `Could not ${action} the ${spec.label} service`,
    `${spec.label} on ${server.hostname} is "${state}" after the ${action}, not active. ` +
      `Diagnose with: systemctl status <unit> ; journalctl -u <unit> -n 50`,
    href
  );
  throw new Error(`game power: ${action} left service in state=${state}`);
}

// Real port-bound check — the same in-guest positive-confirmation path
// PROVISION uses (worker/provision-health.ts's checkGamePortOpen +
// gamePortBoundInGuest), reused here for the other place this class of bug
// hid: a systemd unit reporting "active" proves the OBJECT exists, never
// that the game process inside actually bound its port. Best-effort and
// deliberately short (GAME_POWER_PORT_CHECK_TIMEOUT_MS) — families with no
// GAME_PORT entry, or a NAT server whose game port isn't forwarded, skip
// this silently rather than block or falsely fail on a check that can't
// mean anything for them.
if (action !== "stop" && state === "active") {
  const game = gamePortForServer(server);
  const checkHost = server.dedicatedIp?.address ?? server.node?.publicIp ?? null;
  if (game && checkHost) {
    const portCheck = await checkGamePortOpen(checkHost, game.port, game.protocol, {
      timeoutMs: GAME_POWER_PORT_CHECK_TIMEOUT_MS,
      intervalMs: GAME_POWER_PORT_CHECK_INTERVAL_MS,
      verifyBound: () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol),
    });
    if (!portCheck.ok) {
      await notify(
        server.userId,
        `${spec.label} service ${action}ed, but the game never came online`,
        `systemd reports ${server.hostname} as active, but nothing is actually answering on ` +
          `${game.port}/${game.protocol}: ${portCheck.error ?? "no further detail"}. Check the game's own logs — ` +
          `this usually means the server process itself failed to start even though its service is "running".`,
        href
      );
      throw new Error(`game power: ${action} reported active but port ${game.port}/${game.protocol} never bound: ${portCheck.error ?? ""}`);
    }
  }
}

await notify(
  server.userId,
  `${spec.label} service ${action}ed on ${server.hostname}`,
  action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
  href
);

